function homePage(g,user){const s=status(g.id),c=s.settings,en=guildManager.isModuleEnabled(g.id,'verification'),flow=c.flow?.orderedSecurity||[],active=SECURITY.filter(([key])=>c.security?.[key]===true).length;const embed=emb(emojiLabel('SECURITY', 'Verification'),[en?`**Enabled** ${EMOJIS.SUCCESS}`:`**Disabled** ${EMOJIS.ERROR}`,'Manage member access, security checks and verification panels.'],user,en?0x57F287:0x5865F2).addFields({name:'1 · 🚪 Member journey',value:'New member → Pending → Verifying → Verified',inline:false},{name:'2 · 🛡️ Security overview',value:`**Methods enabled:** ${active}/${SECURITY.length}\n**Flow steps:** ${flow.length}\n**Intelligence:** ${c.intelligence?.enabled?'🟢 Enabled':'🔴 Disabled'}\n**Attempt limit:** ${c.security?.maximumFailedAttempts??5}`,inline:false},{name:'3 · 📊 Verification activity',value:`**Verified:** ${s.analytics?.verified||0}   ·   **Failed:** ${s.analytics?.failed||0}   ·   **Quarantined:** ${s.analytics?.quarantined||0}`,inline:false},{name:'4 · ⚙️ Manage Verification',value:'**Roles:** Configure access and staff roles.\n**Security:** Manage checks, flow and access policies.\n**Panel:** Deploy and customise the member message.\n**Messages:** Edit verification templates.\n**Logs:** Configure channel and session logging.\n**Settings:** Manage operation, raid protection and diagnostics.',inline:false});return{embeds:[embed],components:[...homeNav(),homeFinalNav()]};}
